import type { Database } from '@ccc/runtime';
import { Game, type GameState } from './game.js';

export class GameStore {
  constructor(private db: Database) {}

  async load(id: string): Promise<Game | null> {
    const result = await this.db.query<{ state: GameState }>(
      'SELECT state FROM games WHERE id = $1',
      [id]
    );

    if (result.rows.length === 0) {
      return null;
    }

    return Game.fromState(result.rows[0].state);
  }

  async save(game: Game): Promise<void> {
    const state = game.toState();
    const stateJson = JSON.stringify(state);

    await this.db.query(
      'INSERT INTO games (id, state) VALUES ($1, $2) ON CONFLICT (id) DO UPDATE SET state = $2',
      [game.id, stateJson]
    );
  }
}
